create table app_user (id uuid primary key, email text not null unique, password_hash text not null, display_name text not null, role text not null default 'USER', timezone text not null default 'Asia/Kolkata', preferred_time text, language text not null default 'en', wellness_goal text, referral_code text not null unique, disabled boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), version bigint not null default 0);
create table refresh_token (id uuid primary key, user_id uuid not null references app_user(id), token_hash text not null unique, expires_at timestamptz not null, revoked boolean not null default false, created_at timestamptz not null default now());
create table instructor (id uuid primary key, name text not null, bio text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table program (id uuid primary key, name text not null unique, description text not null, difficulty text not null, duration_minutes integer not null, program_type text not null, image_url text, instructor_id uuid references instructor(id), active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), version bigint not null default 0);
create table program_enrollment (id uuid primary key, user_id uuid not null references app_user(id), program_id uuid not null references program(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(user_id,program_id));
create table class_series (id uuid primary key, program_id uuid not null references program(id), instructor_id uuid references instructor(id), local_time time not null, timezone text not null, days_of_week text not null default 'MON,TUE,WED,THU,FRI,SAT,SUN', duration_minutes integer not null, youtube_video_id text, active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table session (id uuid primary key, series_id uuid references class_series(id), program_id uuid not null references program(id), instructor_id uuid references instructor(id), starts_at timestamptz not null, ends_at timestamptz not null, timezone text not null, status text not null default 'SCHEDULED', delivery_type text not null default 'LIVE', youtube_video_id text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), version bigint not null default 0, unique(series_id,starts_at));
create table attendance (id uuid primary key, user_id uuid not null references app_user(id), session_id uuid not null references session(id), joined_at timestamptz not null, last_seen_at timestamptz not null, left_at timestamptz, watched_seconds bigint not null default 0, qualified boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), version bigint not null default 0, unique(user_id,session_id));
create table attendance_heartbeat (id uuid primary key, attendance_id uuid not null references attendance(id), request_id text not null unique, occurred_at timestamptz not null, created_at timestamptz not null default now());
create table streak (user_id uuid primary key references app_user(id), current_days integer not null default 0, longest_days integer not null default 0, last_qualifying_date date, total_qualified_days integer not null default 0, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), version bigint not null default 0);
create table habit_definition (id uuid primary key, name text not null, active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table habit_log (id uuid primary key, user_id uuid not null references app_user(id), habit_id uuid not null references habit_definition(id), logged_date date not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(user_id,habit_id,logged_date));
create table challenge (id uuid primary key, name text not null, duration_days integer not null, start_date date, end_date date, required_program_id uuid references program(id), daily_requirement integer not null default 1, reward text, active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table challenge_enrollment (id uuid primary key, user_id uuid not null references app_user(id), challenge_id uuid not null references challenge(id), progress_days integer not null default 0, completed boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(user_id,challenge_id));
create table achievement (id uuid primary key, code text not null unique, name text not null, description text, threshold integer not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table user_achievement (id uuid primary key, user_id uuid not null references app_user(id), achievement_id uuid not null references achievement(id), created_at timestamptz not null default now(), unique(user_id,achievement_id));
create table notification_template (id uuid primary key, code text not null unique, body text not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table notification (id uuid primary key, user_id uuid not null references app_user(id), channel text not null, body text not null, status text not null default 'PENDING', dedupe_key text not null unique, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table notification_delivery (id uuid primary key, notification_id uuid not null references notification(id), status text not null, error text, created_at timestamptz not null default now());
create table referral (id uuid primary key, referrer_id uuid not null references app_user(id), invitee_id uuid not null unique references app_user(id), status text not null default 'REGISTERED', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table content (id uuid primary key, title text not null, body text not null, object_key text, published boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table audit_log (id uuid primary key, actor_id uuid references app_user(id), action text not null, entity_type text not null, entity_id uuid, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
create table outbox_event (id uuid primary key, event_type text not null, event_version integer not null default 1, aggregate_id uuid not null, correlation_id text, payload jsonb not null, published_at timestamptz, attempts integer not null default 0, created_at timestamptz not null default now());
create table processed_event (consumer text not null, event_id uuid not null, created_at timestamptz not null default now(), primary key(consumer,event_id));
create index idx_session_starts on session(starts_at); create index idx_outbox_pending on outbox_event(created_at) where published_at is null; create index idx_attendance_user on attendance(user_id); create index idx_notification_pending on notification(created_at) where status='PENDING';
